-- V006 Sync Categories, Products, Variants, and Images
USE FashionStoreDB;
GO

ALTER TABLE Categories NOCHECK CONSTRAINT ALL;
GO
SET IDENTITY_INSERT Categories ON;
DELETE FROM Categories WHERE CategoryId = 49;
MERGE INTO Categories AS target
USING (VALUES
  (37, N'Balo', 9, 'unisex', NULL),
  (38, N'Túi đeo chéo', 9, 'unisex', NULL),
  (39, N'Túi xách tay', 9, 'nu', NULL),
  (40, N'Ví nam', 9, 'nam', NULL),
  (41, N'Đồng hồ', 10, 'unisex', NULL),
  (42, N'Kính mát', 10, 'unisex', NULL),
  (43, N'Mũ', 10, 'unisex', NULL),
  (44, N'Khăn', 10, 'unisex', NULL),
  (45, N'Áo hoodie nam', 11, 'nam', NULL),
  (46, N'Áo hoodie nữ', 11, 'nu', NULL),
  (47, N'Áo polo nam', 12, 'nam', NULL),
  (48, N'Áo polo nữ', 12, 'nu', NULL)
) AS source (CategoryId, Name, ParentId, Gender, Season)
ON target.CategoryId = source.CategoryId
WHEN MATCHED THEN UPDATE SET Name = source.Name, ParentId = source.ParentId, Gender = source.Gender, Season = source.Season
WHEN NOT MATCHED THEN INSERT (CategoryId, Name, ParentId, Gender, Season) VALUES (source.CategoryId, source.Name, source.ParentId, source.Gender, source.Season);
SET IDENTITY_INSERT Categories OFF;
ALTER TABLE Categories CHECK CONSTRAINT ALL;
GO

